import { tool } from "ai"
import { z } from "zod"
import { toolOutput } from "./lib/tool-output"

export const TodoItem = z.object({
	id: z.string().describe("Unique identifier for the todo item"),
	content: z.string().describe("Brief description of the task"),
	status: z
		.enum(["pending", "in_progress", "completed", "cancelled"])
		.describe("Current status of the task"),
})

export type TodoItem = z.infer<typeof TodoItem>

export interface TodoStorage {
	get: () => Promise<TodoItem[]>
	set: (todos: TodoItem[]) => Promise<void>
}

function createInMemoryStorage(): TodoStorage {
	let todos: TodoItem[] = []
	return {
		get: async () => todos,
		set: async (newTodos) => {
			todos = newTodos
		},
	}
}

const TODO_READ_DESCRIPTION = `Read the current todo list for this session.

Use this tool frequently to stay aware of task status:
- At the beginning of conversations to see what's pending
- Before starting new tasks to prioritize work
- When uncertain about what to do next
- After completing tasks to update your understanding

Returns a list of todo items with their id, content, and status.
If no todos exist, an empty list is returned.`

const TODO_WRITE_DESCRIPTION = `Create and manage a structured task list for the current session.

## When to Use
- Complex multi-step tasks (3+ distinct steps)
- User provides multiple tasks (numbered or comma-separated)
- After receiving new instructions - capture requirements as todos
- After completing a task - mark complete and add follow-ups
- When starting a task - mark as in_progress (only one at a time)

## When NOT to Use
- Single, straightforward tasks
- Trivial tasks completable in <3 steps
- Purely conversational/informational requests

## Task States
- pending: Not yet started
- in_progress: Currently working on (limit to ONE at a time)
- completed: Finished successfully
- cancelled: No longer needed

## Task Management
- Update status in real-time as you work
- Mark tasks complete IMMEDIATELY after finishing
- Only have ONE task in_progress at any time
- Complete current tasks before starting new ones`

export function createTodoTools(storage?: TodoStorage) {
	const store = storage ?? createInMemoryStorage()
	const outputSchema = toolOutput({
		pending: {},
		success: {
			todos: z.array(TodoItem),
			count: z.number(),
			pending: z.number(),
		},
		error: {},
	})

	const todoRead = tool({
		description: TODO_READ_DESCRIPTION,
		inputSchema: z.object({}),
		outputSchema,
		async execute() {
			const todos = await store.get()
			const pending = todos.filter(
				(t) => t.status === "pending" || t.status === "in_progress",
			).length

			return {
				status: "success",
				message:
					todos.length === 0
						? "No todos yet."
						: `Retrieved ${todos.length} todos.`,
				todos,
				count: todos.length,
				pending,
			}
		},
	})

	const todoWrite = tool({
		description: TODO_WRITE_DESCRIPTION,
		inputSchema: z.object({
			todos: z.array(TodoItem).describe("The complete updated todo list"),
		}),
		outputSchema,
		async execute({ todos }) {
			await store.set(todos)
			const pending = todos.filter(
				(t) => t.status === "pending" || t.status === "in_progress",
			).length

			return {
				status: "success",
				message:
					todos.length === 0
						? "Cleared all todos."
						: `Saved ${todos.length} todos.`,
				todos,
				count: todos.length,
				pending,
			}
		},
	})

	return { todoRead, todoWrite }
}

import { z } from "zod"

export const truncation = {
	truncated: z.boolean().optional(),
	truncationReason: z.string().optional(),
}

export const continuationHint = {
	continuationHint: z.string().optional(),
}

export const continuationOffset = {
	continuationOffset: z.number().optional(),
}

/**
 * Creates a union schema for tool output with pending, success, error, and optional streaming states.
 * This ensures consistent output structure across all tools.
 */
export function toolOutput<
	P extends Record<string, z.ZodTypeAny>,
	S extends Record<string, z.ZodTypeAny>,
	E extends Record<string, z.ZodTypeAny>,
	T extends Record<string, z.ZodTypeAny> | undefined = undefined,
>({
	pending,
	success,
	error,
	streaming,
}: {
	pending: P
	success: S
	error: E
	streaming?: T
}) {
	return z.union([
		z.object({
			status: z.literal("pending"),
			message: z.string(),
			...pending,
		}),
		z.object({
			status: z.literal("success"),
			message: z.string(),
			...success,
		}),
		z.object({
			status: z.literal("error"),
			message: z.string(),
			error: z.string(),
			...error,
		}),
		...(streaming
			? [
					z.object({
						status: z.literal("streaming"),
						message: z.string(),
						...streaming,
					}),
				]
			: []),
	])
}
